@startuml

class SensorController {
}

class Apartment {
  +address : string
}

class Inhabitant {
  +username : string
  +password : string
}

class Room {
  +description : string
}

abstract class Sensor {
  +vendorId : string
  +description : string
  +unit : Unit
}

class TemperatureSensor extends Sensor {
  +min : float
  +max : float
}

class PowerSensor extends Sensor {
  +counterReading : float
}

class MeasuredValue {
  +timestamp : datetime
  +value : float
}

class EMonitor {
}

enum Unit {
  CELSIUS
  WATT
}

Apartment "1" *-- "2..*" Room
Apartment "1" -- "1" SensorController
Apartment "1" -- "0..1" String : emailAddress
SensorController "1" -- "*" Inhabitant
SensorController "1" -- "*" MeasuredValue
SensorController "1" -- "*" Sensor
Room "1" -- "1" Sensor
Sensor "1" -- "*" MeasuredValue
EMonitor "1" -- "*" Sensor : checks thresholds
EMonitor "1" -- "1" SensorController : sends alerts

@enduml

